package com.altnautica.gcs.radio.rx.aux

import com.altnautica.gcs.radio.rx.auxmux.AuxChannel
import com.altnautica.gcs.radio.rx.auxmux.AuxMuxDecoder
import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The phone's aux-lane writers and readers against vectors generated by the
 * agent's encoder tests (`ground_vectors_*` in ados-protocol and
 * ados-config-tunnel), byte for byte.
 */
class AuxLaneVectorTest {
    private val vectors: Map<String, ByteArray> =
        checkNotNull(javaClass.classLoader!!.getResource("ground-vectors/aux-lane.txt")).readText().lines()
            .filter { it.startsWith("VECTOR ") }
            .associate { line -> line.split(' ').let { it[1] to hex(it[2]) } }

    private fun v(name: String) = checkNotNull(vectors[name]) { "vector $name missing" }

    @Test
    fun `aux frames match the agent's framing`() {
        assertArrayEquals(v("aux_mavlink"), AuxMuxDecoder.encode(AuxChannel.MAVLINK, "payload bytes".toByteArray()))
        assertArrayEquals(v("aux_pilot"), AuxMuxDecoder.encode(AuxChannel.PILOT, byteArrayOf(7, 0x81.toByte(), 0xA1.toByte())))
        assertArrayEquals(v("aux_empty_request"), AuxMuxDecoder.encode(AuxChannel.REQUEST, ByteArray(0)))
        assertNull("a payload over 1200 bytes is refused, never split", AuxMuxDecoder.encode(AuxChannel.MAVLINK, ByteArray(1201)))
    }

    @Test
    fun `link feedback records match the agent's encoder`() {
        val measured = LinkFeedback(5.25, -61.4, 12.4, 485, 3, 7_850, hasMeasurement = true, targetSlot = 2)
        val deaf = LinkFeedback(0.0, -100.0, -3.0, 0, 0, 0, hasMeasurement = false, targetSlot = 1)
        assertArrayEquals(v("feedback_measured"), measured.encode())
        assertArrayEquals(v("feedback_deaf"), deaf.encode())
    }

    @Test
    fun `relay requests match the agent's encoder`() {
        val body = """{"key":"video.wfb.fleet_slot","value":3}""".toByteArray()
        val ticket = "v2|relay.http|drone-1|1700000000|1700000030|0f1e2d3c4b5a69788796a5b4c3d2e1f0|PUT|/api/config|" +
            "db0739877f3454d122c168b355e29b4ab05933592034fd4d5c270358772ca5c1|2e786ce19bf7095c8698eb6ef44f5445f2217caa3685cf2c4ab2eac2de1d48d8"
        val put = RelayRpc.encodeRequest(3, 0x01020304, "drone-1".toByteArray(), "/api/config".toByteArray(), "application/json".toByteArray(), ticket.toByteArray(), body)!!
        assertEquals(1, put.size)
        assertArrayEquals(v("rpc_request_put"), put[0])
        val big = ByteArray(2600) { (it % 251).toByte() }
        val frags = RelayRpc.encodeRequest(2, 7, "drone-1".toByteArray(), "/api/mission".toByteArray(), "application/octet-stream".toByteArray(), ByteArray(0), big)!!
        assertEquals(3, frags.size)
        frags.forEachIndexed { i, f -> assertArrayEquals("fragment $i", v("rpc_request_big_$i"), f) }
    }

    private fun fragments(name: String) = vectors.keys.filter { it.startsWith("rpc_response_${name}_") }.sorted().map { v(it) }

    /** Feeds [frags] (minus [drop]) to a client's pending call and returns its answer. */
    private fun answer(frags: List<ByteArray>, drop: Set<Int>): RelayResult = runBlocking {
        lateinit var client: RelayRequestClient
        client = RelayRequestClient(send = { frame ->
            // The request went up: the drone answers with id 0x0A0B0C0D, rewritten to the request's id.
            val id = frame.copyOfRange(AuxMuxDecoder.HEADER_LEN + 1, AuxMuxDecoder.HEADER_LEN + 5)
            frags.forEachIndexed { i, f ->
                if (i !in drop) client.onResponse(f.copyOf().also { id.copyInto(it, 8) })
            }
            true
        }, timeoutMs = 2_000)
        client.call("drone-1", "GET", "/api/status", null, ByteArray(0), secretHex = null)
    }

    @Test
    fun `a small answer rebuilds from repair symbols alone`() {
        val r = answer(fragments("small"), drop = setOf(0)) as RelayResult.Answered
        assertEquals(200, r.response.status)
        assertEquals("""{"ok":true}""", r.response.body.decodeToString())
    }

    @Test
    fun `a large answer rebuilds with source symbols lost and keeps its headers`() {
        val frags = fragments("big")
        assertEquals(7, frags.size)
        val r = answer(frags, drop = setOf(0, 2)) as RelayResult.Answered
        assertEquals(200, r.response.status)
        assertArrayEquals(ByteArray(2500) { ((it * 7 + 3) and 0xFF).toByte() }, r.response.body)
        assertEquals(listOf("content-type" to "application/octet-stream"), r.response.headers)
    }

    @Test
    fun `an empty answer completes on its one fragment`() {
        val r = answer(fragments("empty"), drop = emptySet()) as RelayResult.Answered
        assertEquals(204, r.response.status)
        assertEquals(0, r.response.body.size)
    }

    @Test
    fun `another drone's fragments never complete the call`() {
        val foreign = fragments("small").map { f -> f.copyOf().also { it[7] = '9'.code.toByte() } }
        assertEquals(RelayResult.Failed(RelayFailure.Timeout), answer(foreign, drop = emptySet()))
    }

    @Test
    fun `config tunnel request frames match the agent's framing`() {
        val body = ConfigTunnelClient.requestBody(
            "drone-1", "put", "video.wfb.bitrate", "8000", SECRET, 1_700_000_000, "0f1e2d3c4b5a69788796a5b4c3d2e1f0",
        )
        assertArrayEquals(v("tunnel_request_body"), body)
        val frames = TunnelFrames.request(5, body, firstSeq = 0)!!
        assertEquals(3, frames.size)
        frames.forEachIndexed { i, f -> assertArrayEquals("frame $i", v("tunnel_request_$i"), f) }
    }

    @Test
    fun `config tunnel answers reassemble from the agent's frames`() = runBlocking {
        lateinit var client: ConfigTunnelClient
        client = ConfigTunnelClient(send = { _ ->
            // The agent's response frames carry request id 5; this client's first request is id 1.
            for (i in 2 downTo 0) {
                val chunk = TunnelFrames.parse(v("tunnel_response_$i"))!!
                val frame = TunnelFrames.frame(rechunk(chunk, 1), i, 1, 1)
                client.onFrame(frame)
            }
            true
        }, timeoutMs = 2_000)
        val r = client.get("drone-1", "radio", SECRET) as TunnelResult.Answered
        assertTrue(!r.isError)
        assertEquals("""{"blob":"${"z".repeat(300)}"}""", r.body.decodeToString())
    }

    private fun rechunk(c: TunnelFrames.Chunk, id: Int): ByteArray {
        val out = ByteArray(TunnelFrames.HEADER_LEN + c.data.size)
        out[0] = 0xAD.toByte()
        out[1] = 0x03
        out[2] = 1
        out[3] = 1
        out[4] = id.toByte()
        out[8] = c.seq.toByte()
        out[10] = c.total.toByte()
        c.data.copyInto(out, TunnelFrames.HEADER_LEN)
        return out
    }

    private companion object {
        const val SECRET = "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff"

        fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
    }
}
